CREATE OR REPLACE FUNCTION Fix_TBI_InTrn_fn() RETURNS TRIGGER AS $$
DECLARE
BEGIN
  NEW.CQnt := NEW.Qnt;
  If COALESCE(NEW.CQnt,0)<0 THEN
    RAISE EXCEPTION '%', 'No Qnt. For The Item '||NEW.Fixd_Id;
  END If;
  If COALESCE(NEW.CQnt,0)=0 AND COALESCE(NEW.CAmt,0)<>0 THEN
    RAISE EXCEPTION '%', 'Fixd '||NEW.Fixd_Id||' Has Amount Without Quantity';
  END If;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

