CREATE OR REPLACE FUNCTION Fix_TBI_OuTrn_fn() RETURNS TRIGGER AS $$
DECLARE
  nPrice    NUMERIC := 0;
BEGIN
  SELECT Price
    INTO nPrice
    FROM Fix_InTrn
    WHERE Id=NEW.Trn_Id;
  NEW.UCst := COALESCE(nPrice,0);
  NEW.Cst  := COALESCE(NEW.UCst,0) * COALESCE(NEW.Qnt,0);
  UPDATE Fix_InTrn SET
         CQnt=COALESCE(CQnt,0)-COALESCE(NEW.Qnt,0),
         CAmt=COALESCE(CAmt,0)-COALESCE(NEW.Cst,0)
   WHERE Id=NEW.Trn_Id;
EXCEPTION
  When No_Data_Found THEN
    RAISE EXCEPTION '%', 'Undefined Transaction '||NEW.Trn_Id;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

